CREATE TYPE character_status AS ENUM ('draft', 'confirmed');
CREATE TYPE generation_status AS ENUM ('queued', 'generating', 'success', 'error', 'cancelled');
CREATE TYPE generation_asset_kind AS ENUM ('video', 'image', 'thumbnail');
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,story text NOT NULL,duration_seconds integer NOT NULL,aspect_ratio text NOT NULL,genre text,visual_style jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE characters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name text NOT NULL,canon jsonb NOT NULL DEFAULT '{}'::jsonb,character_sheet jsonb,status character_status NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE character_states (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,name text NOT NULL,category text NOT NULL,priority integer NOT NULL DEFAULT 50,changes jsonb NOT NULL DEFAULT '{}'::jsonb,carry_forward boolean NOT NULL DEFAULT false,conflicts_with jsonb NOT NULL DEFAULT '[]'::jsonb,replaces jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name text NOT NULL,canon jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE props (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name text NOT NULL,canon jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scenes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,scene_order integer NOT NULL,title text NOT NULL,description text NOT NULL,location_id uuid REFERENCES locations(id) ON DELETE SET NULL,environment jsonb NOT NULL DEFAULT '{}'::jsonb,mood jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scene_characters (scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,character_id uuid NOT NULL REFERENCES characters(id) ON DELETE CASCADE,active_state_ids jsonb NOT NULL DEFAULT '[]'::jsonb,scene_overrides jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY (scene_id, character_id));
CREATE TABLE scene_props (scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,prop_id uuid NOT NULL REFERENCES props(id) ON DELETE CASCADE,state jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY (scene_id, prop_id));
CREATE TABLE shots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scene_id uuid NOT NULL REFERENCES scenes(id) ON DELETE CASCADE,shot_order integer NOT NULL,title text NOT NULL,description text NOT NULL,duration_seconds numeric(6,2) NOT NULL,character_direction jsonb NOT NULL DEFAULT '{}'::jsonb,camera jsonb NOT NULL DEFAULT '{}'::jsonb,lighting jsonb NOT NULL DEFAULT '{}'::jsonb,environment_overrides jsonb NOT NULL DEFAULT '{}'::jsonb,shot_overrides jsonb NOT NULL DEFAULT '{}'::jsonb,first_frame_asset_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE generations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shot_id uuid NOT NULL REFERENCES shots(id) ON DELETE CASCADE,provider text NOT NULL,status generation_status NOT NULL DEFAULT 'queued',provider_job_id text,resolved_snapshot jsonb NOT NULL,compiled_prompt text NOT NULL,settings jsonb NOT NULL DEFAULT '{}'::jsonb,error jsonb,selected boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE generation_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),generation_id uuid NOT NULL REFERENCES generations(id) ON DELETE CASCADE,kind generation_asset_kind NOT NULL,url text NOT NULL,mime_type text NOT NULL,width integer,height integer,duration_seconds numeric(8,3),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX characters_project_idx ON characters(project_id);
CREATE INDEX scenes_project_order_idx ON scenes(project_id, scene_order);
CREATE INDEX shots_scene_order_idx ON shots(scene_id, shot_order);
CREATE INDEX generations_shot_created_idx ON generations(shot_id, created_at DESC);
